package com.example.hdr;

import android.app.Activity;
import android.content.Intent;
import android.net.Uri;
import android.os.Bundle;
import android.os.Environment;
import android.widget.*;
import com.arthenica.ffmpegkit.FFmpegKit;
import com.arthenica.ffmpegkit.ReturnCode;
import java.io.*;

public class MainActivity extends Activity {
    TextView status;

    @Override
    protected void onCreate(Bundle b) {
        super.onCreate(b);
        LinearLayout root = new LinearLayout(this);
        root.setOrientation(LinearLayout.VERTICAL);
        root.setPadding(40, 80, 40, 40);

        Button pick = new Button(this);
        pick.setText("اختار فيديو");
        status = new TextView(this);
        status.setPadding(0, 40, 0, 0);

        root.addView(pick);
        root.addView(status);
        setContentView(root);

        pick.setOnClickListener(v -> {
            Intent i = new Intent(Intent.ACTION_GET_CONTENT);
            i.setType("video/*");
            startActivityForResult(i, 1);
        });
    }

    @Override
    protected void onActivityResult(int req, int res, Intent data) {
        super.onActivityResult(req, res, data);
        if (req == 1 && res == RESULT_OK && data != null) {
            convert(data.getData());
        }
    }

    void convert(Uri uri) {
        status.setText("جاري التحويل... (ياخذ وقت)");
        new Thread(() -> {
            try {
                File in = new File(getCacheDir(), "in.mp4");
                try (InputStream is = getContentResolver().openInputStream(uri);
                     OutputStream os = new FileOutputStream(in)) {
                    byte[] buf = new byte[8192];
                    int n;
                    while ((n = is.read(buf)) > 0) os.write(buf, 0, n);
                }

                File dir = getExternalFilesDir(Environment.DIRECTORY_MOVIES);
                File out = new File(dir, "hdr_" + System.currentTimeMillis() + ".mp4");

                String cmd = "-y -i " + in.getAbsolutePath()
                    + " -vf zscale=t=linear:npl=100,format=gbrpf32le,"
                    + "zscale=p=bt2020,zscale=t=smpte2084:m=bt2020nc:r=tv,"
                    + "format=yuv420p10le"
                    + " -c:v libx265 -preset ultrafast -crf 22"
                    + " -x265-params colorprim=bt2020:transfer=smpte2084:"
                    + "colormatrix=bt2020nc:hdr10=1:repeat-headers=1"
                    + " -c:a copy " + out.getAbsolutePath();

                FFmpegKit.executeAsync(cmd, session -> {
                    boolean ok = ReturnCode.isSuccess(session.getReturnCode());
                    runOnUiThread(() -> status.setText(ok
                        ? "تمّ ✅\n" + out.getAbsolutePath()
                        : "فشل ❌"));
                });
            } catch (Exception e) {
                runOnUiThread(() -> status.setText("خطأ: " + e.getMessage()));
            }
        }).start();
    }
}
